    ('e7487d60-6487-532d-a368-ebdfdb12a036'::uuid, 'fa11d0bb-a41a-52a2-947d-6bd62be296b5'::uuid, 'Combien vaut 2/3 + 1/4 ?', 'mcq', '["11/12","3/7","2/12","3/12"]'::jsonb, 0, '8/12 + 3/12.', 2),
