    ('11b3ad3f-4907-5860-ba53-959a122c595c'::uuid, 'a4a158c1-1ba3-5523-ab1a-f567b5b8a774'::uuid, 'Comment réduire 3x + 5 + 2x − 1 ?', 'mcq', '["5x + 4","5x + 6","6x + 4","10x"]'::jsonb, 0, 'On regroupe les termes en x d’un côté, les nombres de l’autre.', 6),
