    ('f17dd073-59ff-578a-8624-1b03edbbbfd2'::uuid, 'a4a158c1-1ba3-5523-ab1a-f567b5b8a774'::uuid, 'Les termes 3x et 3x² peuvent être regroupés.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ce ne sont pas des termes de même nature.', 8),
    ('5353399d-c33d-5da4-b400-238c0de46ac5'::uuid, '37a1a339-c78b-563d-86c9-5ca1a4b6f9a8'::uuid, 'Qu’est-ce que résoudre une équation ?', 'mcq', '["Trouver toutes les valeurs de l’inconnue qui rendent l’égalité vraie","Développer les deux membres","Simplifier l’écriture","Vérifier une égalité connue"]'::jsonb, 0, 'Ces valeurs sont les solutions.', 1),
