    ('ae315c7a-dcc1-53b5-bb6d-3c45483230f0'::uuid, '37a1a339-c78b-563d-86c9-5ca1a4b6f9a8'::uuid, 'Combien de solutions a l’équation 0x = 0 ?', 'mcq', '["Une infinité","Aucune","Une seule","Deux"]'::jsonb, 0, 'Tous les nombres conviennent.', 6),
    ('b5a419da-ab75-50ad-a117-d0f34438cc84'::uuid, '37a1a339-c78b-563d-86c9-5ca1a4b6f9a8'::uuid, 'Par quoi doit se terminer la résolution d’un problème mis en équation ?', 'mcq', '["Une phrase de conclusion répondant à la question posée","Le calcul de x","La vérification seule","Le développement de l’équation"]'::jsonb, 0, 'La solution de l’équation n’est pas encore la réponse au problème.', 7),
    ('21b902ac-dd16-56f7-8f73-5aae648bac6b'::uuid, '37a1a339-c78b-563d-86c9-5ca1a4b6f9a8'::uuid, 'On peut diviser les deux membres d’une équation par n’importe quel nombre.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le nombre doit être non nul.', 8),
    ('2feb99fb-a529-545b-9203-1589787974ba'::uuid, '57978780-e661-5d0f-a616-ff06d05daf17'::uuid, 'Que signifie modéliser une situation ?', 'mcq', '["La traduire en objets mathématiques pour la résoudre","La dessiner à l’échelle","La résumer en une phrase","La comparer à une autre situation"]'::jsonb, 0, 'Expression, équation, tableau ou graphique selon le cas.', 1),
