    ('adcfc42c-d2e7-5360-9df3-874631aa1f81'::uuid, '766ce027-ba58-5e42-851f-8827d33560ed'::uuid, 'Quelle représentation convient à une évolution dans le temps ?', 'mcq', '["La courbe","Le diagramme circulaire","Le diagramme en bâtons","Le tableau d’effectifs seul"]'::jsonb, 0, 'Le diagramme circulaire montre une répartition, pas une évolution.', 6),
    ('d5c6e0bf-3f8b-5d70-bea2-d60a36cbc175'::uuid, '766ce027-ba58-5e42-851f-8827d33560ed'::uuid, 'Que faut-il lire en premier sur un graphique ?', 'mcq', '["Les axes et l’échelle","La hauteur des barres","Le titre seulement","La légende des couleurs"]'::jsonb, 0, 'Un axe qui ne part pas de zéro déforme la perception.', 7),
