    ('57cfa255-30ac-51d1-bcb5-f6a7dc3302f2'::uuid, 'e5cdaa19-81b3-55a9-bace-c381bc536cca'::uuid, 'Que dit la loi des grands nombres ?', 'mcq', '["La fréquence observée se rapproche de la probabilité quand on répète beaucoup","Le prochain résultat devient prévisible","Toutes les issues sortent le même nombre de fois exactement","La probabilité augmente avec le nombre d’essais"]'::jsonb, 0, 'Elle ne dit rien d’un tirage isolé.', 7),
