    ('b12608d7-e919-57f1-90e8-18f2698310c3'::uuid, 'cafa0221-771e-5d4e-bbb0-7f906d025246'::uuid, 'Le produit en croix s’applique à n’importe quel tableau de valeurs.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il suppose que la situation soit proportionnelle.', 8),
