    ('2cf3ff1a-8e2b-555b-992c-1fb88b64b2da'::uuid, 'd0fa6777-fa44-5662-a598-07723cfb17e2'::uuid, 'L’aire d’un disque est-elle proportionnelle à son rayon ?', 'mcq', '["Non, elle dépend du carré du rayon","Oui, avec le coefficient π","Oui, avec le coefficient 2π","Elle n’en dépend pas"]'::jsonb, 0, 'La courbe n’est pas une droite.', 6),
    ('dff2b1ce-5b0e-555a-b569-f17b9499368f'::uuid, 'd0fa6777-fa44-5662-a598-07723cfb17e2'::uuid, 'Quelles sont les trois façons de décrire une dépendance ?', 'mcq', '["Une formule, un tableau, un graphique","Un texte, un dessin, un calcul","Une équation, une inéquation, un système","Un tableur, une calculatrice, un compas"]'::jsonb, 0, 'Les trois décrivent la même relation.', 7),
    ('64222ab6-31b4-58ec-81f5-efb384032cf1'::uuid, 'd0fa6777-fa44-5662-a598-07723cfb17e2'::uuid, 'Toute dépendance entre deux grandeurs est une proportionnalité.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est l’inverse qui est vrai : toute proportionnalité est une dépendance.', 8),
