    ('ef961f44-feea-5afa-96bb-5ad962662116'::uuid, '221e41e7-ddc6-5108-be4c-d892d8199532'::uuid, 'Comment calcule-t-on la vitesse moyenne d’un aller-retour ?', 'mcq', '["Distance totale ÷ durée totale","Moyenne des deux vitesses","Somme des deux vitesses","Vitesse de l’aller uniquement"]'::jsonb, 0, 'La moyenne des vitesses donnerait un résultat faux.', 5),
    ('cfe96ba7-038b-5355-9318-8b359e0b026f'::uuid, '221e41e7-ddc6-5108-be4c-d892d8199532'::uuid, 'En combien de temps un robinet de 12 L/min remplit-il 150 L ?', 'mcq', '["12,5 min","18 min","1 800 min","12 min"]'::jsonb, 0, '150 ÷ 12.', 6),
