    ('748f5dc5-7f60-535b-ac0c-a7dbda21d377'::uuid, '221e41e7-ddc6-5108-be4c-d892d8199532'::uuid, 'Une vitesse moyenne indique les vitesses réellement atteintes pendant le trajet.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle ne dit rien du détail : seule la vitesse instantanée le fait.', 8),
    ('b55538fe-0bdb-5e06-ac62-836e316cdc24'::uuid, '8f70defe-eb9e-5632-92f8-2ac377aac67d'::uuid, 'Combien de faces, d’arêtes et de sommets a un pavé droit ?', 'mcq', '["6 faces, 12 arêtes, 8 sommets","4 faces, 8 arêtes, 6 sommets","8 faces, 12 arêtes, 6 sommets","6 faces, 8 arêtes, 12 sommets"]'::jsonb, 0, 'Le cube en est le cas particulier.', 1),
