    ('bc2a12e1-fe22-5582-a171-99136957999f'::uuid, '8f70defe-eb9e-5632-92f8-2ac377aac67d'::uuid, 'Que sont deux droites non coplanaires ?', 'mcq', '["Deux droites qui ne sont pas dans un même plan et ne se coupent jamais","Deux droites parallèles","Deux droites perpendiculaires","Deux droites confondues"]'::jsonb, 0, 'Ce cas n’existe pas dans le plan.', 5),
    ('7983c442-4f43-5bdf-891b-7231e663f84c'::uuid, '8f70defe-eb9e-5632-92f8-2ac377aac67d'::uuid, 'Quelle est la formule du volume d’un pavé droit ?', 'mcq', '["L × l × h","2(L + l + h)","L × l","(L × l × h) ÷ 3"]'::jsonb, 0, 'Le tiers concernerait une pyramide.', 6),
