    ('fbcc7ba6-5347-5578-828d-5b6ae603f37f'::uuid, '8f70defe-eb9e-5632-92f8-2ac377aac67d'::uuid, 'Deux plans sécants se coupent en un point.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ils se coupent selon une droite.', 8),
    ('12439f20-f9e1-5a76-b91b-2ee17ef09e4a'::uuid, 'ef05898f-791b-51f7-8e52-d1da3e4b7e66'::uuid, 'Quelle est la formule du volume d’une pyramide ?', 'mcq', '["(1/3) × aire de la base × hauteur","Aire de la base × hauteur","(1/2) × aire de la base × hauteur","Périmètre de la base × hauteur"]'::jsonb, 0, 'La même formule vaut pour le cône.', 1),
    ('cd7e6d04-e3de-5b97-9b52-51404e82732c'::uuid, 'ef05898f-791b-51f7-8e52-d1da3e4b7e66'::uuid, 'Quelle est la formule du volume d’un cône de rayon R et de hauteur h ?', 'mcq', '["(1/3) × π × R² × h","π × R² × h","(4/3) × π × R³","2 × π × R × h"]'::jsonb, 0, 'C’est l’aire du disque de base, multipliée par la hauteur puis divisée par 3.', 2),
    ('8314b4e5-3a74-58a6-9511-ee063014e581'::uuid, 'ef05898f-791b-51f7-8e52-d1da3e4b7e66'::uuid, 'Comment obtient-on un cône de révolution ?', 'mcq', '["En faisant tourner un triangle rectangle autour d’un côté de l’angle droit","En faisant tourner un carré","En empilant des disques de même rayon","En pliant un secteur circulaire seulement"]'::jsonb, 0, 'L’hypoténuse engendre la surface latérale.', 3),
    ('3c831647-859e-563c-a103-09b8744007af'::uuid, 'ef05898f-791b-51f7-8e52-d1da3e4b7e66'::uuid, 'Qu’est-ce que la génératrice d’un cône ?', 'mcq', '["L’hypoténuse du triangle qui l’engendre, du sommet au bord de la base","Le rayon de la base","La hauteur du cône","Le diamètre du disque"]'::jsonb, 0, 'C’est le rayon du secteur dans le patron.', 4),
    ('a5d4dd62-3085-5f5a-b6ec-cb397ecf008f'::uuid, 'ef05898f-791b-51f7-8e52-d1da3e4b7e66'::uuid, 'De quoi se compose le patron d’un cône ?', 'mcq', '["D’un disque et d’un secteur circulaire","D’un disque et d’un triangle","De deux disques","D’un rectangle et d’un disque"]'::jsonb, 0, 'Le rectangle serait le patron latéral d’un cylindre.', 5),
    ('9bebcb70-d215-5dfb-8a84-2998924439a0'::uuid, 'ef05898f-791b-51f7-8e52-d1da3e4b7e66'::uuid, 'Qu’est-ce qu’un tétraèdre ?', 'mcq', '["Une pyramide à base triangulaire","Une pyramide à base carrée","Un cône tronqué","Un prisme à trois faces"]'::jsonb, 0, 'Ses quatre faces sont des triangles.', 6),
    ('37a69442-0022-5661-baac-8f68072ebf80'::uuid, 'ef05898f-791b-51f7-8e52-d1da3e4b7e66'::uuid, 'Quelle figure obtient-on en coupant un cône par un plan parallèle à sa base ?', 'mcq', '["Un disque plus petit que la base","Un triangle","Un rectangle","Une ellipse"]'::jsonb, 0, 'C’est une réduction de la base.', 7),
    ('3aeea858-a4a7-52d4-bfc9-f2893337cd98'::uuid, 'ef05898f-791b-51f7-8e52-d1da3e4b7e66'::uuid, 'Une pyramide a le même volume que le prisme de même base et de même hauteur.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle en occupe exactement le tiers.', 8),
    ('e27ea498-bfd7-55e1-8602-0f9cbf92cecb'::uuid, '0e5cebe5-3e83-5bd3-b683-7b1adcee95b5'::uuid, 'Que multiplie un agrandissement de rapport k ?', 'mcq', '["Toutes les longueurs de la figure","Seulement la base","Seulement les aires","Les angles"]'::jsonb, 0, 'Les angles, eux, sont conservés.', 1),
