    ('f93669d2-6043-5196-8d3b-ae4eaa978ff6'::uuid, '0e5cebe5-3e83-5bd3-b683-7b1adcee95b5'::uuid, 'Sur une maquette au 1/50, à quoi correspond une hauteur de 20 cm ?', 'mcq', '["10 m","1 m","100 m","50 cm"]'::jsonb, 0, '20 × 50 = 1 000 cm.', 5),
    ('e58e5635-7ee4-536c-9f0c-4c2d2f1f0acf'::uuid, '0e5cebe5-3e83-5bd3-b683-7b1adcee95b5'::uuid, 'Sur une maquette au 1/50, à quoi correspond une aire de 4 cm² ?', 'mcq', '["10 000 cm²","200 cm²","4 000 cm²","2 500 cm²"]'::jsonb, 0, 'Les aires se multiplient par 50², soit 2 500.', 6),
    ('6c9eadd1-9aae-5430-b193-7128b83c2bdd'::uuid, '0e5cebe5-3e83-5bd3-b683-7b1adcee95b5'::uuid, 'Comment reconnaît-on que deux figures sont un agrandissement l’une de l’autre ?', 'mcq', '["Le rapport des longueurs correspondantes est le même pour toutes les paires","Elles ont la même aire","Elles ont le même périmètre","Elles ont un côté commun"]'::jsonb, 0, 'Ce rapport commun est le coefficient k.', 7),
    ('98322dae-f1ca-5126-8b69-2f43fdb25d41'::uuid, '0e5cebe5-3e83-5bd3-b683-7b1adcee95b5'::uuid, 'Un agrandissement de rapport 3 multiplie l’aire par 3.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il la multiplie par 9, et le volume par 27.', 8),
    ('a20bfb19-0d48-5f05-a4a0-0271681c34f0'::uuid, '488f1eaf-faf4-5c97-9e81-dc7b56fea9b2'::uuid, 'Quand deux triangles sont-ils égaux ?', 'mcq', '["Quand leurs côtés et leurs angles sont deux à deux de même mesure","Quand ils ont la même aire","Quand ils ont un angle commun","Quand ils sont tous deux rectangles"]'::jsonb, 0, 'L’un se superpose exactement à l’autre.', 1),
    ('f6faa7a4-8404-5b13-b483-d6349d535693'::uuid, '488f1eaf-faf4-5c97-9e81-dc7b56fea9b2'::uuid, 'Combien d’angles égaux suffisent pour prouver que deux triangles sont semblables ?', 'mcq', '["Deux","Un seul","Trois obligatoirement","Aucun : il faut les côtés"]'::jsonb, 0, 'Le troisième suit, la somme des angles valant 180°.', 2),
    ('9929d190-0803-5720-b160-35602407b2c8'::uuid, '488f1eaf-faf4-5c97-9e81-dc7b56fea9b2'::uuid, 'Quel est l’un des cas d’égalité des triangles ?', 'mcq', '["Deux côtés et l’angle compris entre eux","Deux angles seulement","Trois angles égaux","Un côté seulement"]'::jsonb, 0, 'Trois angles égaux ne donnent que la similitude.', 3),
    ('ddb7d5f2-1a75-5476-8fd0-31abd6e9856e'::uuid, '488f1eaf-faf4-5c97-9e81-dc7b56fea9b2'::uuid, 'Que vaut le rapport de similitude k ?', 'mcq', '["Le quotient de deux côtés homologues","La différence de deux côtés","La somme des angles","Le rapport des aires"]'::jsonb, 0, 'Il est le même pour les trois paires de côtés.', 4),
    ('ff8e5e67-11a4-536e-84fa-254a9b1a7646'::uuid, '488f1eaf-faf4-5c97-9e81-dc7b56fea9b2'::uuid, 'Si k = 2, dans quel rapport sont les aires de deux triangles semblables ?', 'mcq', '["4","2","8","6"]'::jsonb, 0, 'Les aires sont dans le rapport k².', 5),
    ('4e8daeaa-14f0-5e63-b0b4-bc407b8f3c57'::uuid, '488f1eaf-faf4-5c97-9e81-dc7b56fea9b2'::uuid, 'Que sont deux triangles égaux, en termes de similitude ?', 'mcq', '["Des triangles semblables de rapport 1","Des triangles semblables de rapport 2","Des triangles jamais semblables","Des triangles de même périmètre seulement"]'::jsonb, 0, 'Même forme et même taille.', 6),
    ('924163b0-abeb-543d-81c6-a35fdb2d1ad8'::uuid, '488f1eaf-faf4-5c97-9e81-dc7b56fea9b2'::uuid, 'Quelle configuration produit toujours deux triangles semblables ?', 'mcq', '["La configuration de Thalès","Le losange","Le trapèze quelconque","Le triangle inscrit dans un cercle"]'::jsonb, 0, 'Deux droites parallèles coupées par deux sécantes.', 7),
    ('25e8b8a2-f547-5193-8431-fdfc45439f32'::uuid, '488f1eaf-faf4-5c97-9e81-dc7b56fea9b2'::uuid, 'Deux triangles semblables ont toujours la même aire.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Leurs aires sont dans le rapport k², égal à 1 seulement si les triangles sont égaux.', 8),
    ('536a75ea-2a1b-5c5e-a3d7-554f5c72a4d8'::uuid, 'ec7690be-9447-59ca-aad6-98f73a0a9526'::uuid, 'Quelle hypothèse rend le théorème de Thalès applicable ?', 'mcq', '["Deux droites parallèles coupées par deux sécantes","Un triangle rectangle","Deux cercles de même rayon","Un quadrilatère quelconque"]'::jsonb, 0, 'Le parallélisme est indispensable.', 1),
    ('24914ce9-6219-54ab-8d75-5a0ad8a64e93'::uuid, 'ec7690be-9447-59ca-aad6-98f73a0a9526'::uuid, 'Dans la configuration de Thalès, à quoi est égal AM / AB ?', 'mcq', '["AN / AC","AB / AM","BC / AN","AC / MN"]'::jsonb, 0, 'Les trois quotients AM/AB, AN/AC et MN/BC sont égaux.', 2),
    ('42031f33-a6cb-545e-a5c7-c31cc16a573a'::uuid, 'ec7690be-9447-59ca-aad6-98f73a0a9526'::uuid, 'Comment nomme-t-on la configuration où M et N sont de part et d’autre du sommet ?', 'mcq', '["La configuration papillon","La configuration emboîtée","La configuration pyramidale","La configuration croisée interdite"]'::jsonb, 0, 'Le théorème s’y applique de la même façon.', 3),
    ('555e6943-f387-552d-b24c-46232bdded7e'::uuid, 'ec7690be-9447-59ca-aad6-98f73a0a9526'::uuid, 'À quoi sert la réciproque du théorème de Thalès ?', 'mcq', '["À démontrer que deux droites sont parallèles","À calculer une longueur","À calculer un angle","À déterminer une aire"]'::jsonb, 0, 'Elle exige que les points soient alignés dans le même ordre.', 4),
    ('f4558fb0-8f27-5ea0-ba25-97a447334d39'::uuid, 'ec7690be-9447-59ca-aad6-98f73a0a9526'::uuid, 'Que conclut-on si les deux quotients sont différents ?', 'mcq', '["Les droites ne sont pas parallèles","La figure est fausse","Le théorème s’applique quand même","Les points ne sont pas alignés"]'::jsonb, 0, 'C’est la contraposée.', 5),
    ('798ef303-320a-5656-b135-2eb464869522'::uuid, 'ec7690be-9447-59ca-aad6-98f73a0a9526'::uuid, 'Comment résout-on une égalité de deux quotients ?', 'mcq', '["Par le produit en croix","En additionnant les numérateurs","En prenant la racine carrée","En multipliant par π"]'::jsonb, 0, 'a/b = c/d équivaut à a × d = b × c.', 6),
    ('384b5e68-e4cf-59e8-8c11-680bea589d38'::uuid, 'ec7690be-9447-59ca-aad6-98f73a0a9526'::uuid, 'Que faut-il vérifier avant d’appliquer le théorème ?', 'mcq', '["L’alignement des points et le parallélisme des droites","La longueur des côtés","La mesure des angles","L’aire du triangle"]'::jsonb, 0, 'Ce sont les deux hypothèses du théorème.', 7),
    ('cdde6cfc-704b-5f75-b652-2bc62185218d'::uuid, 'ec7690be-9447-59ca-aad6-98f73a0a9526'::uuid, 'Le théorème de Thalès permet de calculer un angle.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il ne parle que de longueurs.', 8),
    ('89ceb1ab-ec33-5145-a781-53f5808e736e'::uuid, '90b722fc-86b2-53c8-96c1-fcb30d51964c'::uuid, 'Que dit le théorème de Pythagore ?', 'mcq', '["Le carré de l’hypoténuse égale la somme des carrés des deux autres côtés","La somme des angles vaut 180°","Les côtés sont proportionnels","L’aire vaut base × hauteur ÷ 2"]'::jsonb, 0, 'Il ne s’applique qu’au triangle rectangle.', 1),
    ('342bd671-2343-538a-ae20-6416ba52c228'::uuid, '90b722fc-86b2-53c8-96c1-fcb30d51964c'::uuid, 'Comment appelle-t-on le côté opposé à l’angle droit ?', 'mcq', '["L’hypoténuse","Le côté adjacent","La médiane","La hauteur"]'::jsonb, 0, 'C’est toujours le plus long des trois côtés.', 2),
    ('8b4a1ce1-4e55-59a3-b7cc-51ec06c71a23'::uuid, '90b722fc-86b2-53c8-96c1-fcb30d51964c'::uuid, 'Comment calcule-t-on un côté de l’angle droit ?', 'mcq', '["En soustrayant les carrés : AB² = BC² − AC²","En additionnant les carrés","En divisant les longueurs","Avec le cosinus uniquement"]'::jsonb, 0, 'L’ordre de la soustraction compte.', 3),
    ('2ba4f814-c5ae-5334-a5e9-ed596d29bc67'::uuid, '90b722fc-86b2-53c8-96c1-fcb30d51964c'::uuid, 'À quoi sert la réciproque du théorème de Pythagore ?', 'mcq', '["À démontrer qu’un triangle est rectangle","À calculer l’hypoténuse","À calculer un angle","À démontrer un parallélisme"]'::jsonb, 0, 'L’angle droit est alors opposé au plus grand côté.', 4),
    ('1e7601d1-75a2-5caf-bcb0-7e276abec5fe'::uuid, '90b722fc-86b2-53c8-96c1-fcb30d51964c'::uuid, 'Que vaut le cosinus d’un angle aigu ?', 'mcq', '["Côté adjacent ÷ hypoténuse","Côté opposé ÷ hypoténuse","Côté opposé ÷ côté adjacent","Hypoténuse ÷ côté adjacent"]'::jsonb, 0, 'C’est le CAH du moyen mnémotechnique.', 5),
    ('cfa929cb-d795-58ba-81a0-fbbdc0ec3ba9'::uuid, '90b722fc-86b2-53c8-96c1-fcb30d51964c'::uuid, 'Comment retrouve-t-on un angle à partir de son cosinus ?', 'mcq', '["Avec la touche cos⁻¹ de la calculatrice","En multipliant par 90","En prenant la racine carrée","En divisant par π"]'::jsonb, 0, 'La calculatrice doit être en mode degrés.', 6),
    ('0d72cc99-e93e-5620-a820-7fec764f300d'::uuid, '90b722fc-86b2-53c8-96c1-fcb30d51964c'::uuid, 'Que vaut cos 60° ?', 'mcq', '["0,5","1","0","60"]'::jsonb, 0, 'cos 0° = 1 et cos 90° = 0.', 7),
    ('f40c1046-65b5-5107-a4e1-0e81967db234'::uuid, '90b722fc-86b2-53c8-96c1-fcb30d51964c'::uuid, 'Le cosinus d’un angle aigu peut dépasser 1.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un quotient dont le dénominateur est le plus grand côté.', 8),
    ('a4c9426b-5adf-5bca-8b29-944168f93c40'::uuid, '16a91fc2-1ccd-52fa-811a-6cfd897f9296'::uuid, 'Que peut-on dire des diagonales d’un parallélogramme ?', 'mcq', '["Elles se coupent en leur milieu","Elles sont de même longueur","Elles sont perpendiculaires","Elles sont parallèles"]'::jsonb, 0, 'Les autres propriétés distinguent ses cas particuliers.', 1),
    ('a578b84c-6d2b-5f0c-8908-24765e7c7f35'::uuid, '16a91fc2-1ccd-52fa-811a-6cfd897f9296'::uuid, 'Qu’est-ce qu’un rectangle ?', 'mcq', '["Un parallélogramme qui a un angle droit","Un parallélogramme aux côtés égaux","Un quadrilatère aux diagonales perpendiculaires","Un losange aux diagonales égales seulement"]'::jsonb, 0, 'Il en a alors quatre, et ses diagonales sont de même longueur.', 2),
    ('500b0190-d7f0-546f-ab8a-fe6a20d4826e'::uuid, '16a91fc2-1ccd-52fa-811a-6cfd897f9296'::uuid, 'Qu’est-ce qu’un losange ?', 'mcq', '["Un parallélogramme qui a deux côtés consécutifs de même longueur","Un parallélogramme qui a un angle droit","Un quadrilatère aux diagonales de même longueur","Un rectangle penché"]'::jsonb, 0, 'Ses quatre côtés sont alors égaux.', 3),
    ('023c7544-517e-561f-bb5b-ee43b43a5a2d'::uuid, '16a91fc2-1ccd-52fa-811a-6cfd897f9296'::uuid, 'Quelle propriété caractérise les diagonales d’un losange ?', 'mcq', '["Elles sont perpendiculaires","Elles sont de même longueur","Elles sont parallèles","Elles ne se coupent pas"]'::jsonb, 0, 'Elles sont aussi ses axes de symétrie.', 4),
    ('24d1f070-5fb7-54d7-a99a-66f31ad8ca36'::uuid, '16a91fc2-1ccd-52fa-811a-6cfd897f9296'::uuid, 'Qu’est-ce qu’un carré ?', 'mcq', '["Un quadrilatère à la fois rectangle et losange","Un rectangle aux diagonales perpendiculaires seulement","Un losange sans angle droit","Un parallélogramme quelconque"]'::jsonb, 0, 'Il cumule toutes les propriétés.', 5),
    ('1f2702b7-fdca-548b-9d3c-10f48ece688f'::uuid, '16a91fc2-1ccd-52fa-811a-6cfd897f9296'::uuid, 'Combien d’axes de symétrie a un rectangle non carré ?', 'mcq', '["2","4","1","0"]'::jsonb, 0, 'Les médiatrices de ses côtés ; le carré en a 4.', 6),
    ('ce7e1f62-7a4a-510d-bb60-3e7e4fb43078'::uuid, '16a91fc2-1ccd-52fa-811a-6cfd897f9296'::uuid, 'Combien d’axes de symétrie a un parallélogramme quelconque ?', 'mcq', '["Aucun","Un","Deux","Quatre"]'::jsonb, 0, 'Il possède en revanche un centre de symétrie.', 7),
    ('ca433649-b91c-5022-b1b3-4fba488c6d71'::uuid, '16a91fc2-1ccd-52fa-811a-6cfd897f9296'::uuid, 'Un quadrilatère dont les diagonales se coupent en leur milieu et sont perpendiculaires est un rectangle.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un losange : le rectangle a des diagonales de même longueur.', 8),
    ('b4d0b201-10bf-5a63-8e83-8544f53ecee6'::uuid, 'f270a34a-fedc-59af-9cfe-29d64132bd83'::uuid, 'Quelles informations définissent une translation ?', 'mcq', '["Une direction, un sens et une longueur","Un centre et un angle","Un axe seulement","Un rapport de réduction"]'::jsonb, 0, 'On les résume par une flèche.', 1),
    ('80b91161-6cbf-529f-8949-37c2376b0796'::uuid, 'f270a34a-fedc-59af-9cfe-29d64132bd83'::uuid, 'Quelle figure forment A, B, M et son image M′ ?', 'mcq', '["Un parallélogramme","Un rectangle","Un losange","Un triangle"]'::jsonb, 0, 'Le déplacement de A vers B est reporté à partir de M.', 2),
    ('7265200f-342c-5f7c-8baf-6548d551d73e'::uuid, 'f270a34a-fedc-59af-9cfe-29d64132bd83'::uuid, 'Que conserve une translation ?', 'mcq', '["Les longueurs, les angles, les aires et l’orientation","Seulement les angles","Seulement les longueurs","Rien, sauf la forme générale"]'::jsonb, 0, 'Elle change uniquement la position.', 3),
    ('20986252-e9c5-5845-ab30-ad79fff2137d'::uuid, 'f270a34a-fedc-59af-9cfe-29d64132bd83'::uuid, 'Qu’est-ce qui distingue une translation d’une symétrie axiale ?', 'mcq', '["La translation ne retourne pas la figure","La translation ne conserve pas les longueurs","La symétrie axiale ne conserve pas les angles","Il n’y a aucune différence"]'::jsonb, 0, 'Une figure translatée se superpose sans retournement.', 4),
    ('6a51ec1d-776d-5ff5-9a5d-7ae7fc32038c'::uuid, 'f270a34a-fedc-59af-9cfe-29d64132bd83'::uuid, 'Quelle transformation est définie par un centre et un angle ?', 'mcq', '["La rotation","La translation","La symétrie axiale","L’agrandissement"]'::jsonb, 0, 'La symétrie centrale en est le cas particulier à 180°.', 5),
    ('c632b353-d78a-50c7-9431-ac47774336e8'::uuid, 'f270a34a-fedc-59af-9cfe-29d64132bd83'::uuid, 'À quoi équivalent deux translations successives ?', 'mcq', '["À une seule translation, dont les déplacements s’ajoutent","À une rotation","À une symétrie centrale","À un agrandissement"]'::jsonb, 0, 'C’est la première approche de l’addition des vecteurs.', 6),
    ('935f8b95-f182-5d78-b857-16bd5866198a'::uuid, 'f270a34a-fedc-59af-9cfe-29d64132bd83'::uuid, 'Quelles constructions reposent sur la translation ?', 'mcq', '["Les frises et les pavages","Les cercles concentriques","Les triangles semblables","Les diagonales d’un losange"]'::jsonb, 0, 'Un motif y est répété par translation.', 7),
    ('874d0eda-ade7-5a41-96ed-1b35538785e5'::uuid, 'f270a34a-fedc-59af-9cfe-29d64132bd83'::uuid, 'Une translation modifie l’aire de la figure.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle conserve tout, sauf la position.', 8),
    ('0eca886e-aac7-524e-8f85-5e3ddad30701'::uuid, '1502c499-221c-5a0e-add1-6466dce20bef'::uuid, 'Comment traduit-on « les trois quarts de 60 » ?', 'mcq', '["60 × 3/4","60 ÷ 3/4","60 + 3/4","60 − 3/4"]'::jsonb, 0, 'Le mot « de » se traduit par le signe ×.', 1),
    ('8ad50193-20b8-5f63-9db9-9a879c9a1001'::uuid, '1502c499-221c-5a0e-add1-6466dce20bef'::uuid, 'Combien font les trois quarts de 60 ?', 'mcq', '["45","20","80","15"]'::jsonb, 0, '60 ÷ 4 = 15, puis 15 × 3.', 2),
    ('d772a647-ec49-5ac4-bc63-dcc1522f87e1'::uuid, '1502c499-221c-5a0e-add1-6466dce20bef'::uuid, 'À quelle fraction correspond 25 % ?', 'mcq', '["1/4","1/25","25/10","1/2"]'::jsonb, 0, 'Un pourcentage est une fraction de dénominateur 100.', 3),
    ('147a293c-5e5b-59c3-a85a-28b50ffb7bdc'::uuid, '1502c499-221c-5a0e-add1-6466dce20bef'::uuid, 'Combien font 25 % de 80 ?', 'mcq', '["20","25","32","55"]'::jsonb, 0, '80 × 0,25.', 4),
    ('4cca883e-d9d5-57cf-8980-3d57aa3ce8eb'::uuid, '1502c499-221c-5a0e-add1-6466dce20bef'::uuid, 'Combien fait la moitié des trois quarts ?', 'mcq', '["3/8","3/6","1/4","5/8"]'::jsonb, 0, 'On multiplie les deux fractions.', 5),
    ('43f5eb2a-37c7-5971-9db3-e3886bdfbd41'::uuid, '1502c499-221c-5a0e-add1-6466dce20bef'::uuid, 'Si 45 représente les trois quarts d’un nombre, quel est ce nombre ?', 'mcq', '["60","33,75","135","15"]'::jsonb, 0, 'On divise par la fraction : 45 × 4/3.', 6),
    ('4c2f9aa7-f3d7-5875-bb58-6beccbeb9dd7'::uuid, '1502c499-221c-5a0e-add1-6466dce20bef'::uuid, 'Que fait la prise des 5/4 d’une quantité ?', 'mcq', '["Elle l’augmente","Elle la diminue","Elle ne la change pas","Elle l’annule"]'::jsonb, 0, 'Une fraction supérieure à 1 agrandit.', 7),
    ('e3f49fa0-8118-5008-8fc3-1bbf41e9fbdf'::uuid, '1502c499-221c-5a0e-add1-6466dce20bef'::uuid, 'Prendre une fraction d’un nombre revient à diviser par cette fraction.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est une multiplication ; la division sert à retrouver le tout.', 8),
    ('90f80092-cf4c-55e8-b742-b816f16a6629'::uuid, '39477b16-5012-5e28-983d-911021a2efd5'::uuid, 'Que dit l’égalité des produits en croix ?', 'mcq', '["a/b = c/d équivaut à a × d = b × c","a/b = c/d équivaut à a × c = b × d","a/b = c/d équivaut à a + d = b + c","a/b = c/d équivaut à a − b = c − d"]'::jsonb, 0, 'On multiplie le numérateur de l’une par le dénominateur de l’autre.', 1),
    ('34ebe8a9-5310-5ff3-9114-ca15bdb29f27'::uuid, '39477b16-5012-5e28-983d-911021a2efd5'::uuid, 'Les fractions 6/9 et 8/12 sont-elles égales ?', 'mcq', '["Oui, les deux produits valent 72","Non, les numérateurs diffèrent","Non, les dénominateurs diffèrent","On ne peut pas conclure"]'::jsonb, 0, '6 × 12 = 9 × 8 = 72.', 2),
    ('2468a2d5-67da-588a-8e3f-ddd027acc87f'::uuid, '39477b16-5012-5e28-983d-911021a2efd5'::uuid, 'Dans x/12 = 5/4, que vaut x ?', 'mcq', '["15","9,6","60","3"]'::jsonb, 0, '4x = 60.', 3),
    ('39eb1275-cefe-5157-88dd-ed9b7ba18b09'::uuid, '39477b16-5012-5e28-983d-911021a2efd5'::uuid, 'Qu’est-ce que la quatrième proportionnelle ?', 'mcq', '["La valeur manquante d’un tableau de proportionnalité","Le quatrième terme d’une suite","Le coefficient de proportionnalité","La moyenne des trois autres valeurs"]'::jsonb, 0, 'On la calcule par produit en croix.', 4),
    ('fb2cc288-548b-540e-9799-7aec43f595a7'::uuid, '39477b16-5012-5e28-983d-911021a2efd5'::uuid, 'Quelle condition les dénominateurs doivent-ils remplir ?', 'mcq', '["Ils doivent être non nuls","Ils doivent être égaux","Ils doivent être entiers","Ils doivent être premiers"]'::jsonb, 0, 'Une division par zéro n’a pas de sens.', 5),
    ('0015966d-d62d-55bb-ad5c-b21d16ecc13b'::uuid, '39477b16-5012-5e28-983d-911021a2efd5'::uuid, 'À quelle condition le produit en croix est-il valable ?', 'mcq', '["La situation doit être réellement proportionnelle","Les nombres doivent être entiers","Le tableau doit avoir deux lignes","Les valeurs doivent être croissantes"]'::jsonb, 0, 'Appliqué à un tarif avec abonnement, il donne un résultat faux.', 6),
    ('5e3e0e3c-0324-5cd4-909d-84cc313b902f'::uuid, '39477b16-5012-5e28-983d-911021a2efd5'::uuid, 'Quel théorème de géométrie repose entièrement sur cette règle ?', 'mcq', '["Le théorème de Thalès","Le théorème de Pythagore","La réciproque de Pythagore","Le théorème des milieux"]'::jsonb, 0, 'Ses trois quotients égaux se résolvent par produit en croix.', 7),
    ('e9b06766-6352-51b5-8613-480c7ea06a31'::uuid, '39477b16-5012-5e28-983d-911021a2efd5'::uuid, 'Le produit en croix s’applique à n’importe quel tableau de deux lignes.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il suppose la proportionnalité, et l’erreur ne se voit pas dans le calcul.', 8),
    ('e98e4e8c-e52f-57ae-8236-36b5f40c8241'::uuid, 'c4bd6d6e-c38e-5995-b80d-7170c1ab3755'::uuid, 'Quelle égalité définit la division euclidienne ?', 'mcq', '["a = b × q + r, avec 0 ≤ r < b","a = b × q, sans reste","a = b + q + r","a = (b + q) × r"]'::jsonb, 0, 'Le reste doit être strictement inférieur au diviseur.', 1),
    ('12512bc1-c342-5d17-872e-cd265711eccd'::uuid, 'c4bd6d6e-c38e-5995-b80d-7170c1ab3755'::uuid, 'Quelle condition le reste doit-il vérifier ?', 'mcq', '["Être positif et strictement inférieur au diviseur","Être inférieur au quotient","Être toujours nul","Être supérieur au diviseur"]'::jsonb, 0, 'C’est ce qui rend le couple (quotient ; reste) unique.', 2),
    ('c532a16a-2421-542a-aebe-4eba255474f2'::uuid, 'c4bd6d6e-c38e-5995-b80d-7170c1ab3755'::uuid, 'Quel est le reste de la division de 47 par 5 ?', 'mcq', '["2","9","5","7"]'::jsonb, 0, '47 = 5 × 9 + 2.', 3),
    ('83fd13de-068e-57ac-8171-5fea6be5d862'::uuid, 'c4bd6d6e-c38e-5995-b80d-7170c1ab3755'::uuid, 'Que peut-on dire quand le reste est nul ?', 'mcq', '["a est divisible par b, et b est un diviseur de a","a est un diviseur de b","La division est impossible","Le quotient est nul"]'::jsonb, 0, 'a est alors un multiple de b.', 4),
    ('0202615d-c342-5c79-bcb6-9fbd3164a515'::uuid, 'c4bd6d6e-c38e-5995-b80d-7170c1ab3755'::uuid, 'Comment convertit-on 200 minutes en heures et minutes ?', 'mcq', '["3 h et 20 min, car 200 = 60 × 3 + 20","2 h et 40 min","3 h et 40 min","20 h et 3 min"]'::jsonb, 0, 'C’est une division euclidienne par 60.', 5),
    ('e8ade802-f4ea-5b24-9849-7a657d0af294'::uuid, 'c4bd6d6e-c38e-5995-b80d-7170c1ab3755'::uuid, 'Comment reconnaît-on un nombre pair par la division euclidienne ?', 'mcq', '["Son reste dans la division par 2 est nul","Son quotient est pair","Son reste vaut 1","Son diviseur est 2"]'::jsonb, 0, 'Un reste de 1 signale un nombre impair.', 6),
    ('5d8f8b51-98e8-5aed-9f82-689ff8c2bf92'::uuid, 'c4bd6d6e-c38e-5995-b80d-7170c1ab3755'::uuid, 'Dans un problème de partage, que donne le quotient ?', 'mcq', '["Le nombre de parts complètes","Le nombre d’objets restants","Le nombre total d’objets","La taille d’une part"]'::jsonb, 0, 'Le reste donne ce qui n’a pas pu être distribué.', 7),
    ('310ce10b-eaa9-5f51-a2fb-c412b7288217'::uuid, 'c4bd6d6e-c38e-5995-b80d-7170c1ab3755'::uuid, 'Un reste peut être supérieur au diviseur.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Cela signifierait que le quotient est trop petit.', 8),
    ('95a126f1-96ad-5ba5-b940-843e07132b26'::uuid, '8031ccde-e83e-5a9c-bb86-c86615dc2cae'::uuid, 'Si a = b × k avec k entier, que peut-on dire ?', 'mcq', '["a est un multiple de b et b est un diviseur de a","a est un diviseur de b","a et b sont premiers entre eux","a est nécessairement premier"]'::jsonb, 0, 'Les deux phrases disent la même chose.', 1),
    ('11cea957-146a-5735-90ae-59a77c96f4f0'::uuid, '8031ccde-e83e-5a9c-bb86-c86615dc2cae'::uuid, 'Combien un nombre a-t-il de multiples ?', 'mcq', '["Une infinité","Un nombre fini","Autant que de diviseurs","Aucun"]'::jsonb, 0, 'Ses diviseurs, eux, sont en nombre fini.', 2),
    ('85daa8cb-effa-593e-b09d-4432c4a6ca7a'::uuid, '8031ccde-e83e-5a9c-bb86-c86615dc2cae'::uuid, 'Quels sont les diviseurs de 12 ?', 'mcq', '["1, 2, 3, 4, 6 et 12","1, 2, 3, 6 et 12","2, 3, 4 et 6","1, 12 seulement"]'::jsonb, 0, 'On les liste par paires : 1 × 12, 2 × 6, 3 × 4.', 3),
    ('5cc6af43-342c-5623-bbfc-d5378f963004'::uuid, '8031ccde-e83e-5a9c-bb86-c86615dc2cae'::uuid, 'Quel nombre est un multiple de tous les entiers ?', 'mcq', '["0","1","2","Il n’en existe pas"]'::jsonb, 0, '0 = b × 0 pour tout b.', 4),
    ('fa500101-9b60-5ac2-8f33-2ab0ab07cd5c'::uuid, '8031ccde-e83e-5a9c-bb86-c86615dc2cae'::uuid, 'Quel nombre divise tous les entiers ?', 'mcq', '["1","0","2","10"]'::jsonb, 0, 'On ne divise jamais par 0.', 5),
    ('a314d02e-9895-517f-913a-f9266b6086b5'::uuid, '8031ccde-e83e-5a9c-bb86-c86615dc2cae'::uuid, 'Quel est le plus grand diviseur commun de 18 et 24 ?', 'mcq', '["6","3","12","2"]'::jsonb, 0, 'Il permet de simplifier 18/24 en 3/4 d’un coup.', 6),
    ('0ad17be1-46e1-537f-b7c9-29a8555a300f'::uuid, '8031ccde-e83e-5a9c-bb86-c86615dc2cae'::uuid, 'Que signifie « deux nombres premiers entre eux » ?', 'mcq', '["Leur seul diviseur commun est 1","Ce sont deux nombres premiers","Ils se suivent","Leur somme est première"]'::jsonb, 0, 'La fraction qu’ils forment est déjà irréductible.', 7),
    ('b4e56ee9-520f-5a31-8d06-fa27822580ec'::uuid, '8031ccde-e83e-5a9c-bb86-c86615dc2cae'::uuid, 'Un nombre peut avoir une infinité de diviseurs.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ses diviseurs sont en nombre fini ; ce sont ses multiples qui sont infinis.', 8),
    ('c1629222-062e-59b0-9aa7-abbd97795cbe'::uuid, 'ff58f1c1-21d3-5346-9ab9-2ad073ec879f'::uuid, 'Quel est le critère de divisibilité par 3 ?', 'mcq', '["La somme des chiffres est divisible par 3","Le nombre se termine par 3","Le nombre est impair","Les deux derniers chiffres forment un multiple de 3"]'::jsonb, 0, 'Exemple : 2 358 → 2 + 3 + 5 + 8 = 18.', 1),
    ('b0014042-6a5f-5f45-a12c-339fcf89d2ca'::uuid, 'ff58f1c1-21d3-5346-9ab9-2ad073ec879f'::uuid, 'Quel est le critère de divisibilité par 4 ?', 'mcq', '["Les deux derniers chiffres forment un nombre divisible par 4","La somme des chiffres est divisible par 4","Le nombre se termine par 4","Le nombre est pair"]'::jsonb, 0, '1 236 : 36 est divisible par 4.', 2),
    ('fd104c4a-9162-5bbb-abdc-8800b0cf11cb'::uuid, 'ff58f1c1-21d3-5346-9ab9-2ad073ec879f'::uuid, 'Quel est le critère de divisibilité par 9 ?', 'mcq', '["La somme des chiffres est divisible par 9","Le nombre se termine par 9","Le nombre est divisible par 3 deux fois","Les trois derniers chiffres sont divisibles par 9"]'::jsonb, 0, 'C’est le même principe que pour 3.', 3),
    ('c435201b-d2d1-59a0-a136-f1b891c3e2c7'::uuid, 'ff58f1c1-21d3-5346-9ab9-2ad073ec879f'::uuid, 'Par quoi 2 358 est-il divisible ?', 'mcq', '["Par 2, par 3 et par 9","Par 5 seulement","Par 4 et par 10","Par 25"]'::jsonb, 0, 'Somme des chiffres = 18, et il se termine par 8.', 4),
    ('7b0d5957-c9dc-53d2-a1ce-df6ae035222b'::uuid, 'ff58f1c1-21d3-5346-9ab9-2ad073ec879f'::uuid, 'Quel critère caractérise la divisibilité par 5 ?', 'mcq', '["Le nombre se termine par 0 ou 5","Le nombre se termine par 5 uniquement","La somme des chiffres est divisible par 5","Le nombre est impair"]'::jsonb, 0, 'Par 10, il faudrait se terminer par 0.', 5),
    ('accf2d25-c5d4-5536-a702-ebe584c2df3f'::uuid, 'ff58f1c1-21d3-5346-9ab9-2ad073ec879f'::uuid, 'Un nombre divisible par 2 et par 3 est divisible par quel nombre ?', 'mcq', '["6","5","8","12"]'::jsonb, 0, '2 et 3 sont premiers entre eux.', 6),
    ('43f03deb-6b03-59e6-881e-7d7d0280aa5a'::uuid, 'ff58f1c1-21d3-5346-9ab9-2ad073ec879f'::uuid, 'À quoi servent surtout les critères de divisibilité ?', 'mcq', '["À simplifier une fraction et à décomposer un nombre plus vite","À poser une division","À calculer une moyenne","À convertir des unités"]'::jsonb, 0, 'Ils évitent de tâtonner.', 7),
    ('4e2d2333-fc22-5b27-ae33-a739cfc67928'::uuid, 'ff58f1c1-21d3-5346-9ab9-2ad073ec879f'::uuid, 'Un nombre divisible par 2 et par 4 est forcément divisible par 8.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, '2 et 4 ne sont pas premiers entre eux : la règle de combinaison ne s’applique pas.', 8),
    ('e3d9747c-b568-5787-9d5a-c086fe06b862'::uuid, '1b5b41a2-dc0d-5e3e-8fa4-7f1b80004dfb'::uuid, 'Comment calcule-t-on 18 % de 250 ?', 'mcq', '["250 × 0,18","250 ÷ 0,18","250 + 18","18 ÷ 250"]'::jsonb, 0, 'Chercher la partie, c’est multiplier.', 1),
    ('034ea0c0-3a41-5c49-9ce4-1d1c77e94ea0'::uuid, '1b5b41a2-dc0d-5e3e-8fa4-7f1b80004dfb'::uuid, 'Quel pourcentage 45 représente-t-il de 250 ?', 'mcq', '["18 %","45 %","5,5 %","20 %"]'::jsonb, 0, '(45 ÷ 250) × 100.', 2),
    ('5088d460-b08e-5c70-8d3a-9011a30ceed4'::uuid, '1b5b41a2-dc0d-5e3e-8fa4-7f1b80004dfb'::uuid, 'Si 45 représente 18 % d’une quantité, quelle est cette quantité ?', 'mcq', '["250","81","8,1","450"]'::jsonb, 0, 'Chercher le tout, c’est diviser par le coefficient.', 3),
