    ('769c023d-9c9a-599d-a3a6-52a8d9c7a2f2'::uuid, 'bc1b9625-7a79-5577-b6e1-e7eec9fe7d61'::uuid, 'Où se coupent les trois hauteurs ?', 'mcq', '["À l’orthocentre","Au centre de gravité","Au centre du cercle inscrit","Au milieu du plus grand côté"]'::jsonb, 0, 'Les médiatrices, elles, donnent le centre du cercle circonscrit.', 6),
    ('ed89cdcb-59be-57ad-b9dc-dad27dc98cb6'::uuid, 'bc1b9625-7a79-5577-b6e1-e7eec9fe7d61'::uuid, 'Quelle est la formule de l’aire d’un triangle ?', 'mcq', '["(base × hauteur) ÷ 2","base × hauteur","(base + hauteur) ÷ 2","côté²"]'::jsonb, 0, 'La hauteur doit être relative à la base choisie.', 7),
    ('42382ec5-2e4b-5e41-9c88-dd23c67cda56'::uuid, 'bc1b9625-7a79-5577-b6e1-e7eec9fe7d61'::uuid, 'Dans un triangle isocèle, les trois angles sont égaux.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Seuls les deux angles à la base le sont ; les trois angles égaux caractérisent l’équilatéral.', 8)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('maths');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('maths')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 301 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 301 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
